package com.omnivoice.onspeak47.asr;

import android.content.Context;

import com.larplarpsahur.Io;

import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Set;

/**
 * LOCAL file (not in OnSpeak47): whole-file recognition on top of QwenAsrNpuEngine.
 * Language is the tag generated by Qwen, not an inference from letter casing.
 */
public final class QwenFileRecognizer implements AutoCloseable {
    /** One decode covers at most this much audio; upstream cuts streaming utterances at 20 s. */
    static final int MAX_BLOCK = 18 * QwenAsr.SR;
    /** A block boundary moves back to the quietest 100 ms inside this tail window. */
    static final int CUT_WINDOW = 2 * QwenAsr.SR;

    private final QwenAsrNpuEngine engine;

    private QwenFileRecognizer(QwenAsrNpuEngine engine) { this.engine = engine; }

    public static QwenFileRecognizer open(Context context) {
        StreamingAsrEngine e = QwenAsrNpuEngine.tryCreate(context, AsrLanguage.UND);
        if (!(e instanceof QwenAsrNpuEngine)) {
            throw new IllegalStateException("Qwen3-ASR initialization failed. Verify SM8850 model files"
                    + " and QNN runtime; see QwenAsrNpuEngine in logcat.");
        }
        return new QwenFileRecognizer((QwenAsrNpuEngine) e);
    }

    public Recognition transcribe(float[] pcm, Io.Cancellation cancel) throws Exception {
        if (pcm == null || pcm.length < 400) throw new IllegalArgumentException("Audio is shorter than 25 ms");
        StringBuilder text = new StringBuilder(), routed = new StringBuilder();
        Set<String> languages = new LinkedHashSet<>();
        for (int start = 0; start < pcm.length; ) {
            Io.check(cancel);
            int end = blockEnd(pcm, start);
            float[] block = Arrays.copyOfRange(pcm, start, end);
            if (block.length < 400) block = Arrays.copyOf(block, 400);
            start = end;
            String[] result = engine.transcribeFileBlock(block);
            String lang = language(result[0]), part = result[1].trim();
            if (!"und".equals(lang)) languages.add(lang);
            if (part.isEmpty()) continue;
            if (text.length() > 0) { text.append(' '); routed.append(' '); }
            text.append(part);
            routed.append(QwenAsr.scriptConvention(result[0], part));
        }
        return new Recognition(text.toString(), routed.toString(),
                languages.size() == 1 ? languages.iterator().next() : languages.size() > 1 ? "mul" : "und");
    }

    /** End of the block that starts at {@code start}: the rest, or a quiet spot before the limit. */
    static int blockEnd(float[] pcm, int start) {
        if (pcm.length - start <= MAX_BLOCK) return pcm.length;
        return QwenAsr.quietCut(pcm, start + MAX_BLOCK - CUT_WINDOW, start + MAX_BLOCK);
    }

    /**
     * Text of a known language in the script convention the app's MT routing reads
     * (ScriptLid: English words UPPERCASE). Used for reference transcripts in oracle mode.
     */
    public static String routed(String lang, String text) {
        String tag = "en".equals(lang) ? "English" : "zh".equals(lang) ? "Chinese" : "";
        return QwenAsr.scriptConvention(tag, text == null ? "" : text);
    }

    private static String language(String label) {
        switch (label.toLowerCase(Locale.ROOT)) {
            case "vietnamese": case "vi": return "vi";
            case "english": case "en": return "en";
            case "chinese": case "mandarin": case "zh": return "zh";
            default: return "und";
        }
    }

    @Override public void close() { engine.close(); }

    public static final class Recognition {
        /** Transcript as Qwen wrote it (scored against the reference). */
        public final String text;
        /** Same transcript in the app's script convention (input of the MT routing). */
        public final String routedText;
        public final String sourceLanguage;

        Recognition(String text, String routedText, String lang) {
            this.text = text;
            this.routedText = routedText;
            sourceLanguage = lang;
        }
    }
}
